let open Promise.Let_syntax in
[%log internal] "Accumulator_check" ;
let%bind accumulator_check =
  Ipa.Step.accumulator_check
    (List.map ts ~f:(fun (T (_, _, _, _, _, T t)) ->
         ( t.statement.proof_state.messages_for_next_wrap_proof
             .challenge_polynomial_commitment
         , Ipa.Step.compute_challenges
             t.statement.proof_state.deferred_values.bulletproof_challenges
         ) ) )
in
[%log internal] "Accumulator_check_done" ;
Common.time "batch_step_dlog_check" (fun () ->
    check (lazy "batch_step_dlog_check", accumulator_check) ) ;

//~ 1. Setup the Fq-Sponge. This sponge mostly absorbs group
// elements (points as tuples over the base field), but it
// squeezes out elements of the group's scalar field.
let mut fq_sponge = EFqSponge::new(G::other_curve_sponge_params());

//~ 1. Absorb the digest of the VerifierIndex.
let verifier_index_digest = index.digest::<EFqSponge>();
fq_sponge.absorb_fq(&[verifier_index_digest]);

//~ 1. Absorb the commitments of the previous challenges with the Fq-sponge.
for RecursionChallenge { comm, .. } in &self.prev_challenges {
    absorb_commitment(&mut fq_sponge, comm);
}

//~ 1. Absorb the commitment of the public input polynomial with the Fq-Sponge.
absorb_commitment(&mut fq_sponge, public_comm);

//~ 1. Absorb the commitments to the registers / witness columns with the Fq-Sponge.
self.commitments
    .w_comm
    .iter()
    .for_each(|c| absorb_commitment(&mut fq_sponge, c));

// the previous recursion round), and squeezes scalar elements
// of the field. The squeeze result is the same as with the
// `fq_sponge`.
let digest = fq_sponge.clone().digest();
let mut fr_sponge = EFrSponge::from(G::sponge_params());

//~ 1. Squeeze the Fq-sponge and absorb the result with the Fr-Sponge.
fr_sponge.absorb(&digest);

//~ 1. Absorb the previous recursion challenges.
let prev_challenge_digest = {
    // Note: we absorb in a new sponge here to limit the scope in which we need the
    // more-expensive 'optional sponge'.
    let mut fr_sponge = EFrSponge::from(G::sponge_params());
    for RecursionChallenge { chals, .. } in &self.prev_challenges {
        fr_sponge.absorb_multiple(chals);
    }
    fr_sponge.digest()
};
fr_sponge.absorb(&prev_challenge_digest);

// prepare some often used values
let zeta1 = zeta.pow([n]);
let zetaw = zeta * index.domain.group_gen;
let evaluation_points = [zeta, zetaw];
let powers_of_eval_points_for_chunks = PointEvaluations {
    zeta: zeta.pow([index.max_poly_size as u64]),
    zeta_omega: zetaw.pow([index.max_poly_size as u64]),
};

//~ 1. Compute evaluations for the previous recursion challenges.
let polys: Vec<(PolyComm<G>, _)> = self
    .prev_challenges
    .iter()
    .map(|challenge| {
        let evals = challenge.evals(
            index.max_poly_size,
            &evaluation_points,
            &[
                powers_of_eval_points_for_chunks.zeta,
                powers_of_eval_points_for_chunks.zeta_omega,
            ],
        );
        let RecursionChallenge { chals: _, comm } = challenge;
        (comm.clone(), evals)
    })

//~ For every proof we want to verify, we defer the proof opening to the very end.
//~ This allows us to potentially batch verify a number of partially verified proofs.
//~ Essentially, this steps verifies that $f(\zeta) = t(\zeta) * Z_H(\zeta)$.
//~

let zk_rows = verifier_index.zk_rows;

if proof.prev_challenges.len() != verifier_index.prev_challenges {
    return Err(VerifyError::IncorrectPrevChallengesLength(
        verifier_index.prev_challenges,
        proof.prev_challenges.len(),
    ));
}
if public_input.len() != verifier_index.public {
    return Err(VerifyError::IncorrectPubicInputLength(
        verifier_index.public,
    ));
}

//~ 1. Check the length of evaluations inside the proof.
let chunk_size = {
    let d1_size = verifier_index.domain.size();
    if d1_size < verifier_index.max_poly_size {
        1
    } else {
        d1_size / verifier_index.max_poly_size
    }
};
check_proof_evals_len(proof, chunk_size)?;

    //~ Below, we define the steps to verify a number of proofs
    //~ (each associated to a [verifier index](#verifier-index)).
    //~ You can, of course, use it to verify a single proof.
    //~

    //~ 1. If there's no proof to verify, the proof validates trivially.
    if proofs.is_empty() {
        return Ok(());
    }

    //~ 1. Ensure that all the proof's verifier index have a URS of the same length. (TODO: do they have to be the same URS though? should we check for that?)
    // TODO: Account for the different SRS lengths
    let srs = proofs[0].verifier_index.srs();
    for &Context { verifier_index, .. } in proofs {
        if verifier_index.srs().max_poly_size() != srs.max_poly_size() {
            return Err(VerifyError::DifferentSRS);
        }
    }

    //~ 1. Validate each proof separately following the [partial verification](#partial-verification) steps.
    let mut batch = vec![];
    for context in proofs {
        let Context {
            verifier_index,
            proof,
            public_input,
        } = context;

        batch.push(to_batch::<
            FULL_ROUNDS,
            G,
            EFqSponge,
            EFrSponge,
            OpeningProof,
        >(verifier_index, proof, public_input)?);
    }

    //~ 1. Use the [`PolyCom.verify`](#polynomial-commitments) to verify the partially evaluated proofs.
    if OpeningProof::verify(srs, group_map, &mut batch, rng) {
        Ok(())
    } else {
        Err(VerifyError::OpenProof)
    }
}

        G,
        EFqSponge,
        OpeningProof<G, FULL_ROUNDS>,
        FULL_ROUNDS,
    >],
    rng: &mut RNG,
) -> bool
where
    EFqSponge: FqSponge<G::BaseField, G, G::ScalarField, FULL_ROUNDS>,
    RNG: RngCore + CryptoRng,
    G::BaseField: PrimeField,
{
    // Verifier checks for all i,
    // c_i Q_i + delta_i = z1_i (G_i + b_i U_i) + z2_i H
    //
    // if we sample evalscale at random, it suffices to check
    //
    // 0 == sum_i evalscale^i (c_i Q_i + delta_i - ( z1_i (G_i + b_i U_i) + z2_i H ))
    //
    // and because each G_i is a multiexp on the same array self.g, we
    // can batch the multiexp across proofs.
    //
    // So for each proof in the batch, we add onto our big multiexp the
    // following terms
    // evalscale^i c_i Q_i
    // evalscale^i delta_i
    // - (evalscale^i z1_i) G_i
    // - (evalscale^i z2_i) H
    // - (evalscale^i z1_i b_i) U_i

    // We also check that the sg component of the proof is equal to the
    // polynomial commitment to the "s" array

    let nonzero_length = self.g.len();

    let max_rounds = math::ceil_log2(nonzero_length);

    let padded_length = 1 << max_rounds;

    let (_, endo_r) = endos::<G>();

    // TODO: This will need adjusting
    let padding = padded_length - nonzero_length;
    let mut points = vec![self.h];
    points.extend(self.g.clone());
    points.extend(vec![G::zero(); padding]);

    let mut scalars = vec![G::ScalarField::zero(); padded_length + 1];
    assert_eq!(scalars.len(), points.len());

    // sample randomiser to scale the proofs with
    let rand_base = G::ScalarField::rand(rng);
    let sg_rand_base = G::ScalarField::rand(rng);

    let mut rand_base_i = G::ScalarField::one();

sponge.absorb_fr(&[shift_scalar::<G>(*combined_inner_product)]);

let u_base: G = {
    let t = sponge.challenge_fq();
    let (x, y) = group_map.to_group(t);
    G::of_coordinates(x, y)
};

let Challenges { chal, chal_inv } = opening.challenges::<EFqSponge>(&endo_r, sponge);

sponge.absorb_g(&[opening.delta]);
let c = ScalarChallenge::new(sponge.challenge()).to_field(&endo_r);

// Evaluate the challenge polynomial b(X) at each evaluation point and combine.
// This computes: b0 = sum_i evalscale^i * b(evaluation_point[i])
// where b(X) = prod_{j=0}^{k-1} (1 + u_{k-j} * X^{2^j}) is the challenge polynomial
// reconstructed from the IPA challenges `chal`.
let b0 = {
    let mut scale = G::ScalarField::one();
    let mut res = G::ScalarField::zero();
    for &e in evaluation_points.iter() {
        let term = b_poly(&chal, e);
        res += &(scale * term);
        scale *= *evalscale;
    }
    res
};

// Compute the 2^k coefficients of the challenge polynomial b(X).
// These are used in the MSM <s, G> to verify the accumulated commitment.
let s = b_poly_coefficients(&chal);

let neg_rand_base_i = -rand_base_i;

// TERM
// - rand_base_i z1 G
//
// we also add -sg_rand_base_i * G to check correctness of sg.
points.push(opening.sg);
scalars.push(neg_rand_base_i * opening.z1 - sg_rand_base_i);

// Here we add
// sg_rand_base_i * ( < s, self.g > )
// =
// < sg_rand_base_i s, self.g >
//
// to check correctness of the sg component.
{
    let terms: Vec<_> = o1_utils::cfg_iter!(s).map(|s| sg_rand_base_i * s).collect();

    for (i, term) in terms.iter().enumerate() {
        scalars[i + 1] += term;
    }
}

        scalars.push(rand_base_i);
        points.push(opening.delta);

        rand_base_i *= &rand_base;
        sg_rand_base_i *= &sg_rand_base;
    }

    // Verify the equation in two chunks, which is optimal for our SRS size.
    // (see the comment to the `benchmark_msm_parallel_vesta` MSM benchmark)
    let msm_res = {
        #[cfg(feature = "parallel")]
        {
            let chunk_size = points.len() / 2;
            points
                .into_par_iter()
                .chunks(chunk_size)
                .zip(scalars.into_par_iter().chunks(chunk_size))
                .map(|(bases, coeffs)| {
                    let coeffs_bigint = coeffs
                        .into_iter()
                        .map(ark_ff::PrimeField::into_bigint)
                        .collect::<Vec<_>>();
                    G::Group::msm_bigint(&bases, &coeffs_bigint)
                })
                .reduce(G::Group::zero, |mut l, r| {
                    l += r;
                    l
                })
        }
        #[cfg(not(feature = "parallel"))]
        {
            let scalars_bigint: Vec<_> = scalars.iter().map(|x| x.into_bigint()).collect();
            G::Group::msm_bigint(&points, &scalars_bigint)
        }
    };

    msm_res == G::Group::zero()
}
